create table if not exists public.client_ai_entitlements(client_id uuid primary key references public.profiles(id) on delete cascade,enabled boolean not null default false,updated_at timestamptz not null default now(),updated_by uuid);
alter table public.client_ai_entitlements enable row level security;
revoke all on public.client_ai_entitlements from public,anon,authenticated;
create or replace function public.client_ai_status() returns boolean language sql stable security definer set search_path='' as $$ select coalesce((select e.enabled from public.client_ai_entitlements e where e.client_id=auth.uid()),false) $$;
create or replace function public.admin_set_client_ai(p_client_id uuid,p_enabled boolean) returns boolean language plpgsql security definer set search_path='' as $$ begin if not public.is_admin() then raise exception 'Admin access required' using errcode='42501';end if;if not exists(select 1 from public.profiles p where p.id=p_client_id and p.role='client') then raise exception 'Client account not found';end if;insert into public.client_ai_entitlements(client_id,enabled,updated_at,updated_by) values(p_client_id,p_enabled,now(),auth.uid()) on conflict(client_id) do update set enabled=excluded.enabled,updated_at=excluded.updated_at,updated_by=excluded.updated_by;return p_enabled;end $$;
create or replace function public.admin_list_client_ai() returns table(client_id uuid,enabled boolean) language sql stable security definer set search_path='' as $$ select p.id,coalesce(e.enabled,false) from public.profiles p left join public.client_ai_entitlements e on e.client_id=p.id where public.is_admin() and p.role='client' $$;
revoke all on function public.client_ai_status(),public.admin_set_client_ai(uuid,boolean),public.admin_list_client_ai() from public,anon;
grant execute on function public.client_ai_status(),public.admin_set_client_ai(uuid,boolean),public.admin_list_client_ai() to authenticated;
